use flick_render_core::{EvaluatedScene,LinearRgba,Paint,PathCommand,Primitive,SceneLayer,VectorPath,VectorPrimitive};use flick_render_cpu::CpuRenderer;use flick_render_wgpu::{device::RenderDeviceOptions,GpuRenderer,RenderQuality};
#[test]fn gpu_path_matches_cpu_or_declares_cpu_fallback(){let scene=EvaluatedScene{width:8,height:8,background:LinearRgba::TRANSPARENT,layers:vec![SceneLayer{id:"shape".into(),z_index:0,opacity:1.,primitive:Primitive::Vector(VectorPrimitive{path:VectorPath{commands:vec![PathCommand::MoveTo(1.,1.),PathCommand::LineTo(5.,1.),PathCommand::LineTo(5.,5.),PathCommand::LineTo(1.,5.),PathCommand::Close]},fill:Some(Paint::Solid(LinearRgba::from_unpremultiplied(0.,1.,0.,1.))),stroke:None,opacity:1.,transform:[1.,0.,0.,1.,0.,0.]})}],fonts:vec![]};let cpu=CpuRenderer::new();let expected=cpu.render(&scene,0).unwrap();let mut gpu=GpuRenderer::new(RenderDeviceOptions::default()).unwrap();let actual=gpu.render_scene(&scene,RenderQuality::PreviewFull).unwrap();assert_eq!(actual,expected);}
